const crypto = require('node:crypto')
const { configuredRoutes } = require('./control-bound-protocol')

function canonical (value) {
  if (Array.isArray(value)) return value.map(canonical)
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]))
  }
  return value
}

function managedBridgeRevision (panel) {
  const routes = [...configuredRoutes(panel)].map(([id, { control, binding }]) => ({
    id,
    type: control.type,
    mode: control.mode,
    device: binding?.device || '',
    readPath: binding?.readPath || '',
    writePath: binding?.writePath || '',
    readMeta: binding?.readMeta || null,
    writeMeta: binding?.writeMeta || null
  })).sort((a, b) => a.id.localeCompare(b.id))
  const payload = canonical({
    panelId: panel.id,
    room: panel.boundRoom,
    nativeBridge: panel.nativeBridge === true,
    routes
  })
  return `v1:${crypto.createHash('sha256').update(JSON.stringify(payload)).digest('hex')}`
}

module.exports = { managedBridgeRevision, canonical }
